// src/components/BudgetLimits.js
import React, { useState, useEffect } from "react";
import { useLocation } from "react-router-dom";
import axios from "axios";
import "./IncomeCategory.css"; // card/grid styling
import "./Questionnaire.css";  // form styling

function BudgetLimits() {
  const location = useLocation();
  const categories = location.state?.categories || [];

  const [limits, setLimits] = useState({});

  useEffect(() => {
    const initial = {};
    categories.forEach(cat => {
      initial[cat] = ""; // initialize empty limit
    });
    setLimits(initial);
  }, [categories]);

  const handleChange = (cat, value) => {
    setLimits(prev => ({
      ...prev,
      [cat]: value
    }));
  };

  const handleSave = async () => {
    const filteredLimits = {};
    Object.keys(limits).forEach(cat => {
      if (limits[cat] !== "") {
        filteredLimits[cat] = limits[cat];
      }
    });

    if (Object.keys(filteredLimits).length === 0) {
      alert("Please set at least one budget limit");
      return;
    }

    try {
      await axios.post("http://localhost:5000/save-budget", {
        budgetLimits: filteredLimits
      });
      alert("Data saved successfully!");
    } catch (error) {
      console.error(error);
      alert("Failed to save data");
    }
  };

  if (!categories.length) {
    return <p style={{ textAlign: "center", color: "red" }}>No categories with priority ≥ 3</p>;
  }

  return (
    <div className="income-container">
      <h1 className="income-title">Set Monthly Budget Limits</h1>
      <p className="income-subtitle">
        Set your budget for each category with priority ≥ 3
      </p>

      <div className="income-grid">
        {categories.map(cat => (
          <div key={cat} className="income-card">
            <div className="income-name">{cat}</div>
            <input
              type="number"
              placeholder="Enter monthly budget"
              value={limits[cat]}
              onChange={(e) => handleChange(cat, e.target.value)}
              className="form-input"
            />
          </div>
        ))}
      </div>

      <button
        className="next-button"
        style={{ maxWidth: "300px" }}
        onClick={handleSave}
      >
        Save Budget
      </button>
    </div>
  );
}

export default BudgetLimits;
